<?php
class Pelletization extends Model
{
 protected $table='pellet_orders';
 public function references(){return['wastes'=>$this->query("SELECT ws.id,ws.waste_type_id,ws.site_id,ws.quantity_kg,ws.quality_grade,wt.name type_name,pb.batch_number,s.code site_code FROM waste_stocks ws JOIN waste_types wt ON wt.id=ws.waste_type_id LEFT JOIN production_batches pb ON pb.id=ws.production_batch_id JOIN sites s ON s.id=ws.site_id WHERE ws.quantity_kg>0 AND ws.storage_status IN('available','buffer') AND ws.deleted_at IS NULL ORDER BY ws.available_at")->fetchAll(),'waste_types'=>$this->query("SELECT id,code,name FROM waste_types WHERE status='active' AND deleted_at IS NULL")->fetchAll(),'additives'=>$this->query("SELECT a.*,COALESCE(st.quantity_kg,0) quantity_kg,st.id stock_id,COALESCE(st.average_unit_cost,0) average_unit_cost FROM pellet_additives a LEFT JOIN pellet_additive_stocks st ON st.additive_id=a.id AND st.site_id=(SELECT id FROM sites WHERE code='PELL') WHERE a.status='active'")->fetchAll(),'recipes'=>$this->query("SELECT rv.id,r.code,r.name,rv.version_number FROM pellet_recipe_versions rv JOIN pellet_recipes r ON r.id=rv.recipe_id WHERE rv.status='active' ORDER BY r.name,rv.version_number DESC")->fetchAll(),'sites'=>$this->query("SELECT id,code,name FROM sites WHERE status='active' AND deleted_at IS NULL")->fetchAll()];}
 public function compositions(){return ['wastes'=>$this->query('SELECT recipe_version_id,waste_type_id,percentage FROM pellet_recipe_wastes')->fetchAll(),'additives'=>$this->query('SELECT recipe_version_id,additive_id,percentage FROM pellet_recipe_additives')->fetchAll()];}
 public function purchases(){ $params=[];$scope=Auth::siteClause('p.site_id',$params);return $this->query("SELECT p.*,a.name additive_name FROM pellet_additive_purchases p JOIN pellet_additives a ON a.id=p.additive_id WHERE 1=1{$scope} ORDER BY p.id DESC",$params)->fetchAll();}
 public function orders(){$p=[];$s=Auth::siteClause('o.site_id',$p);return$this->query("SELECT o.*,r.code recipe_code,rv.version_number,u.name creator_name,v.name validator_name FROM pellet_orders o JOIN pellet_recipe_versions rv ON rv.id=o.recipe_version_id JOIN pellet_recipes r ON r.id=rv.recipe_id JOIN users u ON u.id=o.created_by LEFT JOIN users v ON v.id=o.validated_by WHERE o.deleted_at IS NULL{$s} ORDER BY o.id DESC",$p)->fetchAll();}
 public function transfers(){return$this->query("SELECT t.*,ss.code source_code,ds.code destination_code,wt.name waste_type,pb.batch_number,l.quantity_kg FROM waste_transfers t JOIN waste_transfer_lines l ON l.transfer_id=t.id JOIN waste_stocks ws ON ws.id=l.source_waste_stock_id JOIN waste_types wt ON wt.id=ws.waste_type_id LEFT JOIN production_batches pb ON pb.id=ws.production_batch_id JOIN sites ss ON ss.id=t.source_site_id JOIN sites ds ON ds.id=t.destination_site_id WHERE t.deleted_at IS NULL ORDER BY t.id DESC")->fetchAll();}
 public function createWasteTransfer(array$d,array$user){$source=Auth::requireCurrentSite();$dest=$this->siteId('PELL');$this->db->beginTransaction();try{$w=$this->row('SELECT * FROM waste_stocks WHERE id=? AND site_id=? AND deleted_at IS NULL FOR UPDATE',[$d['waste_stock_id'],$source]);$qty=(float)$d['quantity_kg'];if(!$w||$qty<=0||$qty>(float)$w['quantity_kg'])throw new RuntimeException('Stock de déchets insuffisant.');$n='BTI-DEC-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO waste_transfers(transfer_number,source_site_id,destination_site_id,status,created_by) VALUES(:n,:s,:d,'draft',:u)",['n'=>$n,'s'=>$source,'d'=>$dest,'u'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO waste_transfer_lines(transfer_id,source_waste_stock_id,quantity_kg) VALUES(:t,:w,:q)',['t'=>$id,'w'=>$w['id'],'q'=>$qty]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BTI',$source,'waste_transfers',$id,'draft',date('Y-m-d H:i:s'),$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function shipWasteTransfer($id,array$user){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM waste_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='draft')throw new RuntimeException('BTI non expédiable.');if((int)$t['created_by']===(int)$user['id']&&!Auth::canSelfValidate($user['id']))throw new RuntimeException('Le créateur ne peut pas valider le BTI.');Auth::requireSiteAccess($t['source_site_id']);$l=$this->row('SELECT * FROM waste_transfer_lines WHERE transfer_id=? FOR UPDATE',[$id]);$w=$this->row('SELECT * FROM waste_stocks WHERE id=? FOR UPDATE',[$l['source_waste_stock_id']]);$q=(float)$l['quantity_kg'];if((float)$w['quantity_kg']<$q)throw new RuntimeException('Stock déchets insuffisant.');$b=(float)$w['quantity_kg'];$this->query("UPDATE waste_stocks SET quantity_kg=quantity_kg-:q,storage_status=IF(quantity_kg-:q2>0,'available','in_transit') WHERE id=:id",['q'=>$q,'q2'=>$q,'id'=>$w['id']]);$this->wasteMove($w,'transfer_out',$q,$b,$b-$q,'waste_transfers',$id,$user);$this->query("UPDATE waste_transfers SET status='in_transit',approved_by=:u,shipped_at=NOW() WHERE id=:id",['u'=>$user['id'],'id'=>$id]);$this->approveDoc('BTI','waste_transfers',$id,$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receiveWasteTransfer($id,array$user){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM waste_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='in_transit')throw new RuntimeException('BTI non réceptionnable ou déjà reçu.');Auth::requireSiteAccess($t['destination_site_id']);$l=$this->row('SELECT l.*,ws.* FROM waste_transfer_lines l JOIN waste_stocks ws ON ws.id=l.source_waste_stock_id WHERE l.transfer_id=? FOR UPDATE',[$id]);$this->query("INSERT INTO waste_stocks(site_id,product_id,waste_type_id,production_batch_id,quantity_kg,quality_grade,available_at,storage_status,status) VALUES(:site,:product,:type,:batch,:qty,:quality,NOW(),'available','active')",['site'=>$t['destination_site_id'],'product'=>$l['product_id'],'type'=>$l['waste_type_id'],'batch'=>$l['production_batch_id'],'qty'=>$l['quantity_kg'],'quality'=>$l['quality_grade']]);$dest=$this->db->lastInsertId();$this->query('UPDATE waste_transfer_lines SET destination_waste_stock_id=:stock WHERE id=:id',['stock'=>$dest,'id'=>$l['id']]);$dw=$this->row('SELECT * FROM waste_stocks WHERE id=? FOR UPDATE',[$dest]);$this->wasteMove($dw,'transfer_in',$l['quantity_kg'],0,$l['quantity_kg'],'waste_transfers',$id,$user);$this->query("UPDATE waste_transfers SET status='received',received_at=NOW() WHERE id=:id",['id'=>$id]);$this->db->commit();return$dest;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function buyAdditive(array$d,array$user){$qty=(float)($d['quantity_kg']??0);$unitCost=(float)($d['unit_cost']??-1);if($qty<=0||$unitCost<0)throw new RuntimeException('Quantité ou coût d’additif invalide.');$site=$this->siteId('PELL');Auth::requireSiteAccess($site);$this->db->beginTransaction();try{$n='ACH-ADD-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO pellet_additive_purchases(site_id,additive_id,purchase_number,quantity_kg,unit_cost,status,created_by) VALUES(:site,:additive,:n,:qty,:cost,'draft',:user)",['site'=>$site,'additive'=>$d['additive_id'],'n'=>$n,'qty'=>$qty,'cost'=>$unitCost,'user'=>$user['id']]);$id=$this->db->lastInsertId();$this->logActivity('create_additive_purchase','pelletization','pellet_additive_purchases',$id,'Création achat additif.',null,['quantity_kg'=>$qty,'unit_cost'=>$unitCost],$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receiveAdditive($id,array$user){$this->db->beginTransaction();try{$p=$this->row('SELECT * FROM pellet_additive_purchases WHERE id=? FOR UPDATE',[$id]);if(!$p||$p['status']!=='draft')throw new RuntimeException('Achat additif déjà traité.');if((int)$p['created_by']===(int)$user['id']&&!Auth::canSelfValidate($user['id']))throw new RuntimeException('Le créateur ne peut pas réceptionner.');$s=$this->additiveStock($p['site_id'],$p['additive_id']);$b=(float)$s['quantity_kg'];$q=(float)$p['quantity_kg'];$a=$b+$q;$cost=$a>0?(($b*(float)$s['average_unit_cost'])+($q*(float)$p['unit_cost']))/$a:0;$this->query('UPDATE pellet_additive_stocks SET quantity_kg=:q,average_unit_cost=:c WHERE id=:id',['q'=>$a,'c'=>$cost,'id'=>$s['id']]);$this->query("INSERT INTO pellet_additive_movements(stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:s,'purchase_in',:q,:b,:a,'pellet_additive_purchases',:r,:u)",['s'=>$s['id'],'q'=>$q,'b'=>$b,'a'=>$a,'r'=>$id,'u'=>$user['id']]);$this->query("UPDATE pellet_additive_purchases SET status='received',approved_by=:u,received_by=:u2,received_at=NOW() WHERE id=:id",['u'=>$user['id'],'u2'=>$user['id'],'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createRecipeVersion(array$d,array$user){$this->db->beginTransaction();try{$recipe=$this->row('SELECT * FROM pellet_recipes WHERE code=? AND deleted_at IS NULL FOR UPDATE',[$d['code']]);if(!$recipe){$this->query("INSERT INTO pellet_recipes(code,name,status,created_by) VALUES(:code,:name,'active',:user)",['code'=>$d['code'],'name'=>$d['name'],'user'=>$user['id']]);$recipe=['id'=>$this->db->lastInsertId()];}$version=(int)$this->query('SELECT COALESCE(MAX(version_number),0)+1 FROM pellet_recipe_versions WHERE recipe_id=:id FOR UPDATE',['id'=>$recipe['id']])->fetchColumn();$this->query("UPDATE pellet_recipe_versions SET status='retired' WHERE recipe_id=:id AND status='active'",['id'=>$recipe['id']]);$this->query("INSERT INTO pellet_recipe_versions(recipe_id,version_number,status,effective_from,notes,created_by) VALUES(:recipe,:version,'active',CURDATE(),:notes,:user)",['recipe'=>$recipe['id'],'version'=>$version,'notes'=>$d['notes'],'user'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO pellet_recipe_wastes(recipe_version_id,waste_type_id,percentage) VALUES(:v,:t,:p)',['v'=>$id,'t'=>$d['waste_type_id'],'p'=>$d['waste_percent']]);$this->query('INSERT INTO pellet_recipe_additives(recipe_version_id,additive_id,percentage) VALUES(:v,:a,:p)',['v'=>$id,'a'=>$d['additive_id'],'p'=>$d['additive_percent']]);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createOrder(array$d,array$user){$site=$this->siteId('PELL');Auth::requireSiteAccess($site);$this->db->beginTransaction();try{$rv=$this->row("SELECT * FROM pellet_recipe_versions WHERE id=? AND status='active' FOR UPDATE",[$d['recipe_version_id']]);if(!$rv)throw new RuntimeException('Version de recette inactive.');$w=$this->row("SELECT * FROM waste_stocks WHERE id=? AND site_id=? AND quantity_kg>0 AND storage_status IN('available','buffer') FOR UPDATE",[$d['waste_stock_id'],$site]);if(!$w)throw new RuntimeException('Lot de déchets PELL indisponible.');$a=$this->additiveStock($site,$d['additive_id']);$total=(float)$d['theoretical_input_kg'];if($total<=0)throw new RuntimeException('Quantité théorique invalide.');$wp=(float)$this->query('SELECT percentage FROM pellet_recipe_wastes WHERE recipe_version_id=:v AND waste_type_id=:t',['v'=>$rv['id'],'t'=>$w['waste_type_id']])->fetchColumn();$ap=(float)$this->query('SELECT percentage FROM pellet_recipe_additives WHERE recipe_version_id=:v AND additive_id=:a',['v'=>$rv['id'],'a'=>$d['additive_id']])->fetchColumn();if(abs(($wp+$ap)-100)>0.001)throw new RuntimeException('La formulation doit totaliser 100 %.');$wq=$total*$wp/100;$aq=$total*$ap/100;if((float)$w['quantity_kg']<$wq||(float)$a['quantity_kg']<$aq)throw new RuntimeException('Stocks théoriques insuffisants.');$n='OF-PELL-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO pellet_orders(site_id,recipe_version_id,order_number,theoretical_input_kg,status,started_at,created_by) VALUES(:site,:rv,:n,:q,'in_progress',NOW(),:u)",['site'=>$site,'rv'=>$rv['id'],'n'=>$n,'q'=>$total,'u'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO pellet_order_waste_consumptions(pellet_order_id,waste_stock_id,theoretical_quantity_kg,unit_cost) VALUES(:o,:s,:q,:c)',['o'=>$id,'s'=>$w['id'],'q'=>$wq,'c'=>$w['average_unit_cost']]);$this->query('INSERT INTO pellet_order_additive_consumptions(pellet_order_id,additive_stock_id,theoretical_quantity_kg,unit_cost) VALUES(:o,:s,:q,:c)',['o'=>$id,'s'=>$a['id'],'q'=>$aq,'c'=>$a['average_unit_cost']]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('OF',$site,'pellet_orders',$id,'draft',date('Y-m-d H:i:s'),$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function submitResults($id,array$d,array$user){$this->db->beginTransaction();try{$o=$this->row('SELECT * FROM pellet_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']!=='in_progress')throw new RuntimeException('OF non saisissable.');$wi=(float)$d['waste_actual_kg'];$ai=(float)$d['additive_actual_kg'];$out=(float)$d['output_quantity_kg'];if(min($wi,$ai,$out)<0)throw new RuntimeException('Quantités invalides.');$input=$wi+$ai;$loss=$input-$out;if($loss<0)throw new RuntimeException('Production récupérée supérieure aux consommations.');$yield=$input>0?$out/$input*100:0;$this->query('UPDATE pellet_order_waste_consumptions SET actual_quantity_kg=:q WHERE pellet_order_id=:id',['q'=>$wi,'id'=>$id]);$this->query('UPDATE pellet_order_additive_consumptions SET actual_quantity_kg=:q WHERE pellet_order_id=:id',['q'=>$ai,'id'=>$id]);$this->query("UPDATE pellet_orders SET actual_input_kg=:input,output_quantity_kg=:out,loss_quantity_kg=:loss,yield_percent=:yield,status='results_submitted',ended_at=NOW() WHERE id=:id",['input'=>$input,'out'=>$out,'loss'=>$loss,'yield'=>$yield,'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function validateOrder($id,array$user){$this->db->beginTransaction();try{$o=$this->row('SELECT * FROM pellet_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']!=='results_submitted')throw new RuntimeException('OF non validable ou déjà validé.');if((int)$o['created_by']===(int)$user['id']&&!Auth::canSelfValidate($user['id']))throw new RuntimeException('Le créateur ne peut pas valider.');Auth::requireSiteAccess($o['site_id']);$wc=$this->row('SELECT * FROM pellet_order_waste_consumptions WHERE pellet_order_id=? FOR UPDATE',[$id]);$ac=$this->row('SELECT * FROM pellet_order_additive_consumptions WHERE pellet_order_id=? FOR UPDATE',[$id]);$w=$this->row('SELECT * FROM waste_stocks WHERE id=? FOR UPDATE',[$wc['waste_stock_id']]);$a=$this->row('SELECT * FROM pellet_additive_stocks WHERE id=? FOR UPDATE',[$ac['additive_stock_id']]);if((float)$w['quantity_kg']<(float)$wc['actual_quantity_kg']||(float)$a['quantity_kg']<(float)$ac['actual_quantity_kg'])throw new RuntimeException('Consommation supérieure au disponible.');$wb=(float)$w['quantity_kg'];$wa=$wb-(float)$wc['actual_quantity_kg'];$this->query("UPDATE waste_stocks SET quantity_kg=:q,storage_status=IF(:q2>0,'available','consumed'),status=IF(:q3>0,'active','inactive') WHERE id=:id",['q'=>$wa,'q2'=>$wa,'q3'=>$wa,'id'=>$w['id']]);$this->wasteMove($w,'pellet_consumption',$wc['actual_quantity_kg'],$wb,$wa,'pellet_orders',$id,$user);$ab=(float)$a['quantity_kg'];$aa=$ab-(float)$ac['actual_quantity_kg'];$this->query('UPDATE pellet_additive_stocks SET quantity_kg=:q WHERE id=:id',['q'=>$aa,'id'=>$a['id']]);$this->query("INSERT INTO pellet_additive_movements(stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:s,'production_out',:q,:b,:a,'pellet_orders',:r,:u)",['s'=>$a['id'],'q'=>$ac['actual_quantity_kg'],'b'=>$ab,'a'=>$aa,'r'=>$id,'u'=>$user['id']]);$cost=(float)$wc['actual_quantity_kg']*(float)$wc['unit_cost']+(float)$ac['actual_quantity_kg']*(float)$ac['unit_cost'];$product=$this->productId('ALIMENT-BETAIL');$this->query("INSERT INTO pellet_stocks(site_id,pellet_order_id,product_id,quantity_kg,status) VALUES(:site,:o,:p,:q,'active')",['site'=>$o['site_id'],'o'=>$id,'p'=>$product,'q'=>$o['output_quantity_kg']]);$pelletStock=$this->db->lastInsertId();$this->query("INSERT INTO pellet_stock_movements(pellet_stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:s,'production_in',:q,0,:a,'pellet_orders',:r,:u)",['s'=>$pelletStock,'q'=>$o['output_quantity_kg'],'a'=>$o['output_quantity_kg'],'r'=>$id,'u'=>$user['id']]);$this->query("UPDATE pellet_orders SET status='validated',validated_by=:u,cost_total=:c,cost_per_kg=:cpk WHERE id=:id",['u'=>$user['id'],'c'=>$cost,'cpk'=>$o['output_quantity_kg']>0?$cost/$o['output_quantity_kg']:0,'id'=>$id]);$this->approveDoc('OF','pellet_orders',$id,$user);$this->logActivity('validate_pellet_order','pelletization','pellet_orders',$id,'Validation atomique des consommations et de la production pellets.',$o,['status'=>'validated','pellet_stock_id'=>$pelletStock],$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function packagingItems(){return$this->query("SELECT id,code,unit_capacity_kg FROM empty_packaging_items WHERE code IN('EMB-A30','EMB-A50') AND status='active' AND deleted_at IS NULL")->fetchAll();}
 public function package($orderId,array$d,array$user){$site=$this->siteId('PELL');Auth::requireSiteAccess($site);$this->db->beginTransaction();try{$o=$this->row("SELECT * FROM pellet_orders WHERE id=? AND status='validated' FOR UPDATE",[$orderId]);$ps=$this->row("SELECT * FROM pellet_stocks WHERE pellet_order_id=? AND status='active' FOR UPDATE",[$orderId]);$item=$this->row("SELECT * FROM empty_packaging_items WHERE id=? AND code IN('EMB-A30','EMB-A50') FOR UPDATE",[$d['packaging_item_id']]);if(!$o||!$ps||!$item)throw new RuntimeException('Lot ou format de pellets invalide.');$bags=(int)$d['bags_count'];$kg=$bags*(float)$item['unit_capacity_kg'];$es=$this->row('SELECT * FROM empty_packaging_stocks WHERE site_id=? AND packaging_item_id=? FOR UPDATE',[$site,$item['id']]);if($bags<=0||(float)$ps['quantity_kg']<$kg||!$es||(int)$es['operational_quantity']<$bags)throw new RuntimeException('Pellets vrac ou sacs vides insuffisants.');$pb=(float)$ps['quantity_kg'];$pa=$pb-$kg;$this->query("UPDATE pellet_stocks SET quantity_kg=:q,status=IF(:q2>0,'active','depleted') WHERE id=:id",['q'=>$pa,'q2'=>$pa,'id'=>$ps['id']]);$eb=(int)$es['operational_quantity'];$this->query('UPDATE empty_packaging_stocks SET operational_quantity=operational_quantity-:b WHERE id=:id',['b'=>$bags,'id'=>$es['id']]);$product=$this->productId('ALIMENT-BETAIL');$this->query("INSERT INTO finished_stocks(site_id,product_id,bag_format_id,packaging_id,quantity_bags,total_weight_kg,status) VALUES(:site,:product,:format,NULL,:bags,:kg,'active')",['site'=>$site,'product'=>$product,'format'=>$item['bag_format_id'],'bags'=>$bags,'kg'=>$kg]);$fs=$this->db->lastInsertId();$this->query('INSERT INTO pellet_packaging(pellet_order_id,pellet_stock_id,packaging_item_id,finished_stock_id,bags_count,total_weight_kg,packaged_at,created_by) VALUES(:o,:ps,:item,:fs,:bags,:kg,NOW(),:u)',['o'=>$orderId,'ps'=>$ps['id'],'item'=>$item['id'],'fs'=>$fs,'bags'=>$bags,'kg'=>$kg,'u'=>$user['id']]);$pid=$this->db->lastInsertId();$this->query("INSERT INTO pellet_stock_movements(pellet_stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:s,'packaging_out',:q,:b,:a,'pellet_packaging',:r,:u)",['s'=>$ps['id'],'q'=>$kg,'b'=>$pb,'a'=>$pa,'r'=>$pid,'u'=>$user['id']]);$this->query("INSERT INTO empty_packaging_movements(stock_id,movement_type,quantity,stock_before,stock_after,unit_cost,reference_type,reference_id,movement_at,created_by) VALUES(:s,'consumption',:q,:b,:a,:c,'pellet_packaging',:r,NOW(),:u)",['s'=>$es['id'],'q'=>$bags,'b'=>$eb,'a'=>$eb-$bags,'c'=>$es['average_unit_cost'],'r'=>$pid,'u'=>$user['id']]);$this->db->commit();return$fs;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 private function additiveStock($site,$additive){$s=$this->row('SELECT * FROM pellet_additive_stocks WHERE site_id=? AND additive_id=? FOR UPDATE',[$site,$additive]);if(!$s){$this->query('INSERT INTO pellet_additive_stocks(site_id,additive_id) VALUES(:s,:a)',['s'=>$site,'a'=>$additive]);$s=$this->row('SELECT * FROM pellet_additive_stocks WHERE site_id=? AND additive_id=? FOR UPDATE',[$site,$additive]);}return$s;}
 private function wasteMove($s,$type,$q,$b,$a,$rt,$rid,$u){$this->query('INSERT INTO waste_stock_movements(waste_stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,movement_at,created_by) VALUES(:s,:t,:q,:b,:a,:rt,:rid,NOW(),:u)',['s'=>$s['id'],'t'=>$type,'q'=>$q,'b'=>$b,'a'=>$a,'rt'=>$rt,'rid'=>$rid,'u'=>$u['id']]);}
 private function approveDoc($code,$entity,$id,$u){$d=$this->query('SELECT d.id,d.status FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code=:c AND d.entity_type=:e AND d.entity_id=:id FOR UPDATE',['c'=>$code,'e'=>$entity,'id'=>$id])->fetch();if($d){$this->query("UPDATE documents SET status='approved',validated_by=:u,validated_at=NOW() WHERE id=:id",['u'=>$u['id'],'id'=>$d['id']]);$this->query("INSERT INTO document_status_history(document_id,old_status,new_status,changed_by,reason) VALUES(:d,:o,'approved',:u,'Validation métier')",['d'=>$d['id'],'o'=>$d['status'],'u'=>$u['id']]);}}
 private function siteId($code){return(int)$this->query("SELECT id FROM sites WHERE code=:c AND status='active' AND deleted_at IS NULL",['c'=>$code])->fetchColumn();}private function productId($code){return(int)$this->query('SELECT id FROM products WHERE code=:c AND deleted_at IS NULL',['c'=>$code])->fetchColumn();}private function row($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetch();}
}
